  'appdemo.label': 'Les étapes',
  'appdemo.titleLead': 'Du raccourci ',
  'appdemo.titleAccent': 'au texte',
  'appdemo.titleTail': '',
  'appdemo.subtitle': 'Placez le curseur dans un champ de texte. Appuyez sur le raccourci clavier, parlez, puis appuyez à nouveau pour arrêter. Avec le collage automatique activé, le texte apparaît à cet endroit si l’application et les autorisations le permettent. Sinon, il est disponible dans le presse-papiers.',
  'appdemo.noSwitch': 'Gardez votre fenêtre d’écriture',
  'appdemo.step1.caption': 'Appuyez sur le raccourci',
  'appdemo.step2.caption': 'Parlez, puis arrêtez',
